INSERT INTO `store_products` (`id`, `name`, `description`, `price`, `image`, `sizes`, `stock`, `active`, `created_at`, `updated_at`) VALUES
(1, '👕 Camiseta Full Print Personalizada', 'Destaca en eventos y competencias con esta camiseta sublimada de alta calidad, con impresión full color al frente y espalda.\n\n✅ Impresión Full Print HD\n✅ Colores vivos y duraderos\n✅ Tela fresca y cómoda\n✅ Diseño exclusivo Cars Audio / Truck Audio\n✅ Personalizable con nombre o logo\n\n📏 Tallas: S, M, L, XL, XXL y XXXL\n\n🧵 Material:\n• Poliéster Premium\n• Ligera y transpirable\n• Secado rápido\n\n🚚 Fabricación por encargo y envíos nacionales.\n\n📲 Solicita la tuya hoy.\n\nKENNION DESIGN\n🎨 Diseños personalizados y sublimación Full Print\n📞 WhatsApp: 6157-0404', 15.00, 'https://f005.backblazeb2.com/file/DJIMMY-PANDA/TIENDA/ChatGPT+Image+16+jun+2026%2C+13_10_36.png', 'S,M,L,XL,XXL', 0, 1, '2026-06-16 14:06:57', '2026-06-16 14:12:57');
